import {useState} from 'react';
import {createRoot} from 'react-dom/client';
import {ChevronsUpDown,Check} from 'lucide-react';
import {ToggleGroup,ToggleGroupItem} from '../../../src/components/shadcn/toggle-group';
import {Input} from '../../../src/components/shadcn/input';
import '../../../src/shadcn.css';
import './weight.css';
const choices=[['400','常规'],['500','中等'],['700','粗体']];
function Combo({initialOpen=false}:{initialOpen?:boolean}){const [value,setValue]=useState('500');const [open,setOpen]=useState(initialOpen);const [editing,setEditing]=useState(false);const [active,setActive]=useState(1);const title=choices.find(x=>x[0]===value)?.[1];return <div className="combo"><div className="combo-input"><Input aria-label="字重数值" role="combobox" aria-expanded={open} aria-controls={initialOpen?'weight-options-expanded':'weight-options'} aria-autocomplete="list" value={editing?value:value+(title?' · '+title:'')} onFocus={()=>{setEditing(true);setOpen(true)}} onChange={e=>setValue(e.target.value.replace(/[^0-9]/g,''))} onKeyDown={e=>{if(e.key==='Escape'){setOpen(false);setEditing(false)}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();setOpen(true);setActive(i=>(i+(e.key==='ArrowDown'?1:2))%3)}if(e.key==='Enter'&&open){setValue(choices[active][0]);setOpen(false);setEditing(false)}}}/><button aria-label="展开字重选项" onClick={()=>setOpen(x=>!x)}><ChevronsUpDown size={14}/></button></div>{open&&<div className="options" role="listbox" id={initialOpen?'weight-options-expanded':'weight-options'}>{choices.map(([n,label],i)=><button key={n} role="option" aria-selected={value===n} className={i===active?'active':''} onMouseDown={e=>e.preventDefault()} onClick={()=>{setValue(n);setOpen(false);setEditing(false)}}><span>{label}</span><span className="option-number">{n}</span>{value===n&&<Check size={14}/>}</button>)}</div>}</div>}
function App(){const [weight,setWeight]=useState('500');return <main><header><h1>字重控件对照</h1><p>相同字号、配色与控件高度</p></header><div className="columns"><section><h2>连体分段</h2><div className="label">字重 <span>继承主题</span></div><div className="weight-controls"><Input aria-label="字重" type="number" min={100} max={900} step={100} value={weight} onChange={e=>setWeight(e.target.value)}/><ToggleGroup type="single" value={weight} onValueChange={v=>v&&setWeight(v)} spacing={0} variant="outline" aria-label="字重">{choices.map(([n,label])=><ToggleGroupItem key={n} value={n}>{label}</ToggleGroupItem>)}</ToggleGroup></div><p className="hint">数字每次增减100；右侧可直接选择常用字重。</p><div className="sample" style={{fontWeight:Number(weight)}}>直播中的每一个瞬间</div></section><section><h2>组合输入框</h2><div className="label">字重 <span>继承主题</span></div><Combo/><p className="hint">可输入数值，也可展开选择常用字重。</p><div className="expanded"><div className="label">展开状态</div><Combo initialOpen/></div></section></div></main>};createRoot(document.getElementById('root')!).render(<App/>);
